header='''import { zodResolver } from "@hookform/resolvers/zod";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { t as translate } from "i18next";
import { AlertCircle, PlusCircle } from "lucide-react";
import { useQueryParams } from "raviger";
import { Ref, useCallback, useEffect, useImperativeHandle, useMemo, useRef, useState } from "react";
import { useForm } from "react-hook-form";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";
import { z } from "zod";

import careConfig from "@/../care.config";
import { DisablingCover } from "@/components/Common/DisablingCover";
import { Alert, AlertDescription } from "@/components/ui/alert";
import Autocomplete from "@/components/ui/autocomplete";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { processExtensions } from "@/hooks/useExtensions";
import useExtensionSchemas from "@/hooks/useExtensionSchemas";
import { ExternalDeliveryItemFields } from "@/pages/Facility/services/inventory/externalSupply/deliveryOrder/ExternalDeliveryItemFields";
import { ProductKnowledgeSelect } from "@/pages/Facility/services/inventory/ProductKnowledgeSelect";
import StockLotSelector from "@/pages/Facility/services/inventory/StockLotSelector";
import useCurrentFacility from "@/pages/Facility/utils/useCurrentFacility";
import { MonetaryComponent, MonetaryComponentType } from "@/types/base/monetaryComponent/monetaryComponent";
import { getComponentsFromChargeItem } from "@/types/billing/chargeItem/chargeItem";
import { ChargeItemDefinitionCreate, ChargeItemDefinitionStatus } from "@/types/billing/chargeItemDefinition/chargeItemDefinition";
import chargeItemDefinitionApi from "@/types/billing/chargeItemDefinition/chargeItemDefinitionApi";
import { ExtensionEntityType } from "@/types/extensions/extensions";
import { ProductCreate, ProductRead, ProductStatusOptions } from "@/types/inventory/product/product";
import productApi from "@/types/inventory/product/productApi";
import { ProductKnowledgeBase } from "@/types/inventory/productKnowledge/productKnowledge";
import { RequestOrderStatus } from "@/types/inventory/requestOrder/requestOrder";
import requestOrderApi from "@/types/inventory/requestOrder/requestOrderApi";
import { SupplyDeliveryCondition, SupplyDeliveryRead, SupplyDeliveryStatus, SupplyDeliveryType, SupplyDeliveryUpdate } from "@/types/inventory/supplyDelivery/supplyDelivery";
import supplyDeliveryApi from "@/types/inventory/supplyDelivery/supplyDeliveryApi";
import { SupplyRequestRead } from "@/types/inventory/supplyRequest/supplyRequest";
import supplyRequestApi from "@/types/inventory/supplyRequest/supplyRequestApi";
import { isEqual, round, zodDecimal } from "@/Utils/decimal";
import { ShortcutBadge } from "@/Utils/keyboardShortcutComponents";
import { useBatchRequest } from "@/Utils/request/batch";
import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";
import { ExtensionContexts } from "@/Utils/schema/types";
import { dateQueryString, dateTimeQueryString } from "@/Utils/utils";

'''
setup='''export interface AddSupplyDeliveryFormHandle {
  editDelivery: (delivery: SupplyDeliveryRead) => void;
}

interface Props {
  ref?: Ref<AddSupplyDeliveryFormHandle>;
  deliveryOrderId: string;
  facilityId: string;
  origin?: string;
  destination: string;
  onSuccess: () => void;
  supplyDeliveriesCount: number;
  isFetchingSupplyDeliveries: boolean;
  currentSupplyDeliveries?: SupplyDeliveryRead[];
  onEditingDeliveryIdsChange?: (ids: string[]) => void;
  onPendingChangesChange?: (hasPendingChanges: boolean) => void;
}

export function AddSupplyDeliveryForm({
  ref,
  deliveryOrderId,
  facilityId,
  origin,
  destination,
  onSuccess,
  supplyDeliveriesCount,
  isFetchingSupplyDeliveries,
  currentSupplyDeliveries,
  onEditingDeliveryIdsChange,
  onPendingChangesChange,
}: Props) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const [qParams, setQueryParams] = useQueryParams();
  const [editorMode, setEditorMode] = useState<"item" | "request" | null>(null);
  const [requestOrderSearch, setRequestOrderSearch] = useState("");
  const [isProcessing, setIsProcessing] = useState(false);
  const [saveError, setSaveError] = useState<string>();
  const savingRef = useRef(false);
  const formElementRef = useRef<HTMLFormElement>(null);
  const { facility } = useCurrentFacility();
  const { getExtensions } = useExtensionSchemas();
  const informationalCodes = facility?.instance_informational_codes || [];
  const allExtensions = getExtensions(ExtensionEntityType.supply_delivery, "write");
  const processedExtensions = useMemo(
    () => processExtensions(allExtensions, ExtensionContexts.supply_delivery_form),
    [allExtensions],
  );

  const createEmptyItem = useCallback(
    (): SupplyDeliveryItemValues => ({
      product_knowledge: {} as ProductKnowledgeBase,
      supplied_inventory_item: "",
      supplied_item_quantity: origin ? "1" : "",
      supplied_item_pack_quantity: undefined,
      supplied_item_pack_size: origin ? undefined : 1,
      _is_inward_stock: !origin,
      is_tax_inclusive: careConfig.inventory.defaultTaxInclusive,
      extensions: {},
    }),
    [origin],
  );

  const form = useForm<SupplyDeliveryFormValues>({
    resolver: zodResolver(createFormSchema),
    defaultValues: {
      supplied_item_type: SupplyDeliveryType.product,
      item: createEmptyItem(),
    },
  });
  const editingDelivery = form.watch("item.replaces_delivery");
  const isEditing = Boolean(editingDelivery);
  const hasPendingChanges = editorMode === "item";
  const isAtItemLimit = supplyDeliveriesCount >= careConfig.maxDatapointsPerUpsert;
  const disableAddItem = isProcessing || isFetchingSupplyDeliveries || isAtItemLimit || editorMode !== null;

  useEffect(() => {
    onEditingDeliveryIdsChange?.(hasPendingChanges && editingDelivery ? [editingDelivery.id] : []);
  }, [hasPendingChanges, editingDelivery, onEditingDeliveryIdsChange]);
  useEffect(() => () => onEditingDeliveryIdsChange?.([]), [onEditingDeliveryIdsChange]);
  useEffect(() => {
    onPendingChangesChange?.(hasPendingChanges);
  }, [hasPendingChanges, onPendingChangesChange]);
  useEffect(() => () => onPendingChangesChange?.(false), [onPendingChangesChange]);

  const { data: supplyRequests } = useQuery({
    queryKey: ["supplyRequests", qParams.supplyOrder],
    queryFn: query.paginated(supplyRequestApi.listSupplyRequest, {
      queryParams: { order: qParams.supplyOrder },
    }),
    enabled: !!qParams.supplyOrder,
  });
  const { data: requestOrders, isLoading: isLoadingRequestOrders } = useQuery({
    queryKey: ["requestOrders", facilityId, requestOrderSearch, destination, origin],
    queryFn: query.debounced(requestOrderApi.listRequestOrder, {
      pathParams: { facilityId },
      queryParams: {
        search: requestOrderSearch || undefined,
        status: RequestOrderStatus.pending,
        ...(!origin ? { destination } : { origin }),
      },
    }),
    enabled: !qParams.supplyOrder,
  });

  const discardChanges = () => {
    if (savingRef.current) return;
    setEditorMode(null);
    setSaveError(undefined);
    form.reset({ supplied_item_type: SupplyDeliveryType.product, item: createEmptyItem() });
  };

  const addItem = (request?: SupplyRequestRead) => {
    if (disableAddItem && editorMode !== "request") return;
    form.reset({
      supplied_item_type: SupplyDeliveryType.product,
      item: {
        ...createEmptyItem(),
        ...(request && {
          product_knowledge: request.item,
          supply_request: request,
          supplied_item_quantity: origin ? request.quantity : "",
        }),
      },
    });
    setSaveError(undefined);
    setEditorMode("item");
  };

  useImperativeHandle(ref, () => ({
    editDelivery: (delivery) => {
      if (origin || isProcessing || isFetchingSupplyDeliveries || editorMode !== null || delivery.status !== SupplyDeliveryStatus.in_progress) return;
      const product = delivery.supplied_item || delivery.supplied_inventory_item?.product;
      if (!product) return;
      const chargeItem = product.charge_item_definition ?? undefined;
      const getComponents = (type: MonetaryComponentType) => chargeItem ? getComponentsFromChargeItem(chargeItem, type) : [];
      const quantity = Number(delivery.supplied_item_quantity);
      let packSize = delivery.supplied_item_pack_size ?? product.standard_pack_size ?? 1;
      let packQuantity = delivery.supplied_item_pack_quantity ?? quantity / packSize;
      if (!Number.isInteger(packQuantity) || packSize * packQuantity !== quantity) {
        packSize = 1;
        packQuantity = quantity;
      }
      form.reset({
        supplied_item_type: delivery.supplied_item_type,
        item: {
          product_knowledge: product.product_knowledge,
          supplied_item: product,
          supplied_item_quantity: String(delivery.supplied_item_quantity),
          supplied_item_pack_size: packSize,
          supplied_item_pack_quantity: packQuantity,
          supply_request: delivery.supply_request,
          _is_inward_stock: true,
          batch_number: product.batch?.lot_number || "",
          expiry_date: dateQueryString(product.expiration_date),
          charge_item_definition: chargeItem,
          charge_item_category: chargeItem?.category?.slug,
          unit_price: getComponents(MonetaryComponentType.base)[0]?.amount ?? "0",
          purchase_price: product.purchase_price ?? undefined,
          total_purchase_price: delivery.total_purchase_price != null ? String(delivery.total_purchase_price) : undefined,
          informational_components: getComponents(MonetaryComponentType.informational),
          tax_components: getComponents(MonetaryComponentType.tax),
          discount_components: getComponents(MonetaryComponentType.discount),
          is_tax_inclusive: false,
          is_manually_edited: false,
          extensions: structuredClone(delivery.extensions || {}),
          replaces_delivery: delivery,
        },
      });
      setSaveError(undefined);
      setEditorMode("item");
    },
  }));

  const validateItem = (item: SupplyDeliveryItemValues) => {
    let message: string | undefined;
    if (origin && !item.supplied_inventory_item) {
      message = t("select_stock");
    } else if (!origin) {
      if (!item.supplied_item || item.is_manually_edited) {
        if (!item.replaces_delivery && !item.batch_number) message = t("delivery_batch_required");
        else if (!item.replaces_delivery && !item.expiry_date) message = t("delivery_expiry_required");
        else if ((!item.supplied_item || item.is_charge_item_edited) && !item.charge_item_category) message = t("delivery_category_required");
      }
      if (!message && item.unit_price === undefined) message = t("delivery_unit_price_required");
    }
    if (message) {
      setSaveError(message);
      toast.error(message);
      return false;
    }
    return true;
  };

'''
submit='''  async function onSubmit(data: SupplyDeliveryFormValues) {
    if (savingRef.current) return;
    setSaveError(undefined);
    if (!validateItem(data.item)) return;
    const original = data.item.replaces_delivery;
    if (original && currentSupplyDeliveries && !currentSupplyDeliveries.some((delivery) => delivery.id === original.id && delivery.status === SupplyDeliveryStatus.in_progress)) {
      const message = t("delivery_item_changed_before_save");
      setSaveError(message);
      toast.error(message);
      return;
    }
    savingRef.current = true;
    setIsProcessing(true);
    try {
      await saveDeliveryItem(data.item, data.supplied_item_type);
      queryClient.invalidateQueries({ queryKey: ["supplyDeliveries"] });
      queryClient.invalidateQueries({ queryKey: ["deliveryOrders"] });
      queryClient.invalidateQueries({ queryKey: ["products", facilityId] });
      queryClient.invalidateQueries({ queryKey: ["chargeItemDefinitions", facilityId] });
      toast.success(t(original ? "items_saved_successfully" : "items_created_successfully", { count: 1 }));
      setEditorMode(null);
      form.reset({ supplied_item_type: SupplyDeliveryType.product, item: createEmptyItem() });
      onSuccess();
    } catch {
      setSaveError(t("delivery_items_save_failed", { count: 1 }));
    } finally {
      savingRef.current = false;
      setIsProcessing(false);
    }
  }

  return (
    <>
      <Card className="bg-gray-50 py-4 rounded-md">
        <CardContent className="flex flex-wrap items-center justify-between gap-4 px-4 sm:px-6">
          <div className="min-w-0 flex-1 basis-64 space-y-1">
            <h3 className="text-base font-semibold">{t("add_item_to_delivery")}</h3>
            <p className="text-sm text-muted-foreground">{t("add_item_to_delivery_description")}</p>
          </div>
          <div className="flex shrink-0 flex-wrap items-center gap-2">
            {qParams.supplyOrder ? (
              !!supplyRequests?.results.length && (
                <Button type="button" variant="outline" onClick={() => setEditorMode("request")} disabled={disableAddItem}>
                  {t("load_from_order")}
                  <ShortcutBadge actionId="load-from-order" />
                </Button>
              )
            ) : (
              <Autocomplete
                options={requestOrders?.results.map((order) => ({ label: order.name, value: order.id })) || []}
                value=""
                onChange={(value) => {
                  if (value) setQueryParams({ ...qParams, supplyOrder: value });
                }}
                isLoading={isLoadingRequestOrders}
                onSearch={setRequestOrderSearch}
                placeholder={t("select_order")}
                inputPlaceholder={t("search_order")}
                noOptionsMessage={t("no_orders_found")}
                className="min-w-40"
                popoverContentClassName="w-auto"
                disabled={disableAddItem}
              />
            )}
            <Button type="button" variant="outline_primary" onClick={() => addItem()} disabled={disableAddItem}>
              <PlusCircle className="size-4" />{t("add_item")}
              <ShortcutBadge actionId="add-item" />
            </Button>
          </div>
        </CardContent>
      </Card>

      <Dialog open={editorMode === "item"} onOpenChange={(open) => { if (!open) discardChanges(); }}>
        <DialogContent
          className="flex max-h-[90dvh] flex-col gap-0 overflow-hidden p-0 sm:max-w-4xl"
          onPointerDownOutside={(event) => event.preventDefault()}
          onEscapeKeyDown={(event) => { if (isProcessing) event.preventDefault(); }}
          onOpenAutoFocus={(event) => {
            if (form.getValues("item.product_knowledge")?.slug) {
              event.preventDefault();
              requestAnimationFrame(() => formElementRef.current?.querySelector<HTMLInputElement>("[data-pending-item-quantity]")?.focus());
            }
          }}
        >
          <DialogHeader className="border-b px-6 py-5 pr-12">
            <DialogTitle>{t(isEditing ? "edit_delivery_item" : "add_item")}</DialogTitle>
            <DialogDescription>{t(isEditing ? "editing_delivery_item_description" : "delivery_item_editor_description")}</DialogDescription>
          </DialogHeader>
          {editorMode === "item" && (
            <Form {...form}>
              <form ref={formElementRef} aria-label={t("pending_changes")} onSubmit={form.handleSubmit(onSubmit, () => {
                const message = t("please_fix_errors");
                setSaveError(message);
